        Patch:

 static const char *tracing_path_tracefs_mount(void)
 {
 	const char *mnt;

 	mnt = tracefs__mount();
 	if (!mnt)
 		return NULL;

 	__tracing_path_set("", mnt);

-	return mnt;
+	return tracing_path;
 }

 static const char *tracing_path_debugfs_mount(void)
 {
 	const char *mnt;

 	mnt = debugfs__mount();
 	if (!mnt)
 		return NULL;

 	__tracing_path_set("tracing/", mnt);

-	return mnt;
+	return tracing_path;
 }



